      --shadow: 0 24px 60px rgba(15, 23, 42, 0.16);
      --primary: #2563eb;
      --danger: #dc2626;
      --danger-strong: #b91c1c;
      --danger-soft: rgba(220, 38, 38, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(37, 99, 235, 0.14), transparent 28%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 32px 20px;
    }

    .shell {
      width: min(100%, 1080px);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(37, 99, 235, 0.1);
      color: var(--primary);
      font-size: 0.875rem;
      font-weight: 600;
      letter-spacing: 0.01em;
    }

    .page-card {
      margin-top: 18px;
      display: grid;
      grid-template-columns: minmax(0, 1.15fr) minmax(280px, 0.85fr);
      gap: 28px;
      padding: 28px;
      background: var(--surface);
      backdrop-filter: blur(18px);
      border: 1px solid rgba(255, 255, 255, 0.7);
      border-radius: 28px;
      box-shadow: var(--shadow);
    }

    .preview-panel,
    .details-panel {
      background: var(--surface-strong);
      border: 1px solid var(--border);
      border-radius: 22px;
    }

    .preview-panel {
      padding: 22px;
    }

    .details-panel {
      padding: 26px;
      display: flex;
      flex-direction: column;
      gap: 20px;
      justify-content: space-between;
    }

    .image-frame {
      margin: 0;
      border-radius: 20px;
      overflow: hidden;
      background: #dbe7ff;
      aspect-ratio: 16 / 10;
      position: relative;
      box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.45);
    }

    .image-frame img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    .image-badge {
      position: absolute;
      top: 16px;
      left: 16px;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(20, 32, 51, 0.74);
      color: #fff;
      font-size: 0.875rem;
      font-weight: 600;
    }

    h1,
    h2,
    p {
      margin: 0;
    }

    h1 {
      font-size: clamp(2rem, 3vw, 3rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .subcopy {
      margin-top: 12px;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.6;
      max-width: 48ch;
    }

    .meta-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
    }

    .meta-card {
      padding: 16px;
      border-radius: 18px;
      background: #f8faff;
      border: 1px solid rgba(37, 99, 235, 0.08);
    }

    .meta-label {
      color: var(--muted);
      font-size: 0.85rem;
      margin-bottom: 8px;
    }

    .meta-value {
      font-size: 1rem;
      font-weight: 700;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      align-items: center;
    }

    button {
      appearance: none;
      border: 0;
      font: inherit;
      cursor: pointer;
      transition: transform 140ms ease, box-shadow 140ms ease, background-color 140ms ease;
    }

    button:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.35);
      outline-offset: 3px;
    }

    .button-secondary,
    .trigger,
    .button-danger {
      min-height: 48px;
      padding: 0 18px;
      border-radius: 14px;
      font-weight: 700;
    }

    .button-secondary {
      color: var(--text);
      background: #eef4ff;
      border: 1px solid rgba(37, 99, 235, 0.12);
    }

    .trigger {
      color: #fff;
      background: linear-gradient(180deg, var(--danger) 0%, var(--danger-strong) 100%);
      box-shadow: 0 12px 24px rgba(220, 38, 38, 0.22);
    }

    .button-danger {
      color: #fff;
      background: linear-gradient(180deg, var(--danger) 0%, var(--danger-strong) 100%);
    }

    .button-secondary:hover,
    .trigger:hover,
    .button-danger:hover {
      transform: translateY(-1px);
    }

    .danger-note {
      display: flex;
      gap: 12px;
      padding: 16px;
      border-radius: 18px;
      background: var(--danger-soft);
      color: #7f1d1d;
      line-height: 1.55;
    }

    .danger-note svg {
      flex: none;
      margin-top: 2px;
    }

    dialog {
      width: min(100% - 32px, 440px);
      border: 0;
      padding: 0;
      border-radius: 24px;
      box-shadow: 0 30px 80px rgba(15, 23, 42, 0.32);
      background: transparent;
    }

    dialog::backdrop {
      background: rgba(15, 23, 42, 0.52);
      backdrop-filter: blur(6px);
    }

    .dialog-card {
      padding: 24px;
      background: #fff;
      border-radius: 24px;
      border: 1px solid rgba(20, 32, 51, 0.08);
    }

    .dialog-icon {
      width: 52px;
      height: 52px;
      display: grid;
      place-items: center;
      border-radius: 16px;
      background: var(--danger-soft);
      color: var(--danger);
      margin-bottom: 18px;
    }

    .dialog-title {
      font-size: 1.5rem;
      letter-spacing: -0.03em;
    }

    .dialog-copy {
      margin-top: 10px;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      margin-top: 24px;
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      flex-wrap: wrap;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 900px) {
      .page-card {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 640px) {
      body {
        padding: 20px 14px;
      }

      .page-card,
      .preview-panel,
      .details-panel {
        border-radius: 22px;
      }

      .page-card {
        padding: 18px;
        gap: 18px;
      }

      .details-panel,
      .preview-panel,
      .dialog-card {
        padding: 18px;
      }

      .meta-grid {
        grid-template-columns: 1fr;
      }

      .dialog-actions,
      .actions {
        flex-direction: column;
      }

      .dialog-actions button,
      .actions button {
        width: 100%;
      }
    }
