<body>
  <div id="app"></div>

  <script>
    const image = {
      title: "Golden Hour Portrait",
      alt: "A woman smiling in warm sunset light near a blue wall",
      src: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=1200&q=80",
      dimensions: "4032 x 3024",
      size: "8.4 MB",
      updated: "Edited 2 hours ago",
      tag: "Portrait"
    };

    const createElement = (markup) => {
      const template = document.createElement("template");
      template.innerHTML = markup.trim();
      return template.content.firstElementChild;
    };

    function Header() {
      return createElement(`
        <header>
          <span class="eyebrow">Library / Image Preview</span>
          <h1>${image.title}</h1>
          <p class="subcopy">Review the details for this asset and remove it from your library only if you no longer need it. Deleting the image cannot be undone.</p>
        </header>
      `);
    }

    function ImagePreviewCard() {
      return createElement(`
        <section class="preview-panel" aria-label="Image preview">
          <figure class="image-frame">
            <img src="${image.src}" alt="${image.alt}">
            <figcaption class="image-badge">${image.tag}</figcaption>
          </figure>
        </section>
      `);
    }

    function DetailsPanel() {
      return createElement(`
        <section class="details-panel" aria-label="Image details">
          <div>
            <h2>Asset details</h2>
            <p class="subcopy">A focused workspace for managing visual content with clear actions and status at a glance.</p>
          </div>
          <div class="meta-grid">
            <div class="meta-card">
              <div class="meta-label">Dimensions</div>
              <div class="meta-value">${image.dimensions}</div>
            </div>
            <div class="meta-card">
              <div class="meta-label">File size</div>
              <div class="meta-value">${image.size}</div>
            </div>
            <div class="meta-card">
              <div class="meta-label">Last update</div>
              <div class="meta-value">${image.updated}</div>
            </div>
            <div class="meta-card">
              <div class="meta-label">Collection</div>
              <div class="meta-value">Campaign Shots</div>
            </div>
          </div>
          <div class="danger-note">
            <svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none">
              <path d="M12 8v5m0 3h.01M10.29 3.86l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.71-3.14l-8-14a2 2 0 0 0-3.42 0Z" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
            <div>Deleting removes this image from your library and any saved organization built around it.</div>
          </div>
          <div class="actions">
            <button type="button" class="button-secondary" aria-label="Keep this image in the library">Keep image</button>
            <button type="button" class="trigger" aria-haspopup="dialog" aria-controls="delete-dialog">Delete image</button>
          </div>
        </section>
      `);
    }

    function ConfirmDeleteDialog() {
      return createElement(`
        <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-description">
          <div class="dialog-card">
            <div class="dialog-icon" aria-hidden="true">
              <svg width="26" height="26" viewBox="0 0 24 24" fill="none">
                <path d="M3 6h18M8 6V4.8A1.8 1.8 0 0 1 9.8 3h4.4A1.8 1.8 0 0 1 16 4.8V6m-8 0 1 12.2A2 2 0 0 0 11 20h2a2 2 0 0 0 2-1.8L16 6M10 10.2v5.6m4-5.6v5.6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
            </div>
            <h2 id="delete-title" class="dialog-title">Delete this image?</h2>
            <p id="delete-description" class="dialog-copy">Are you sure you want to delete <strong>${image.title}</strong> from your library? This action permanently removes the asset.</p>
            <div class="dialog-actions">
              <button type="button" class="button-secondary" data-close-dialog>Cancel</button>
              <button type="button" class="button-danger">Delete permanently</button>
            </div>
          </div>
        </dialog>
      `);
    }

    function App() {
      const shell = createElement(`
        <main class="shell">
          <div class="page-card"></div>
        </main>
      `);

      const pageCard = shell.querySelector(".page-card");
      const leftColumn = createElement(`<div></div>`);
      const rightColumn = DetailsPanel();

      leftColumn.append(Header(), ImagePreviewCard());
      leftColumn.style.display = "grid";
      leftColumn.style.gap = "18px";

      shell.append(ConfirmDeleteDialog());
      pageCard.append(leftColumn, rightColumn);

      return shell;
    }

    const appRoot = document.getElementById("app");
    const app = App();
    appRoot.append(app);

    const dialog = document.getElementById("delete-dialog");
    const trigger = document.querySelector(".trigger");
    const closeButton = dialog.querySelector("[data-close-dialog]");

    trigger.addEventListener("click", () => {
      dialog.showModal();
    });

    closeButton.addEventListener("click", () => {
      dialog.close();
      trigger.focus();
    });

    dialog.addEventListener("click", (event) => {
      const bounds = dialog.getBoundingClientRect();
      const clickedOutside =
        event.clientX < bounds.left ||
        event.clientX > bounds.right ||
        event.clientY < bounds.top ||
        event.clientY > bounds.bottom;

      if (clickedOutside) {
        dialog.close();
        trigger.focus();
      }
    });

    dialog.addEventListener("close", () => {
      if (document.activeElement === document.body) {
        trigger.focus();
      }
    });
  </script>
</body>
