      border: 1px solid var(--border);
      border-radius: 22px;
    }

    .preview-panel {
      padding: 22px;
    }

    .details-panel {
      padding: 26px;
      display: flex;
      flex-direction: column;
      gap: 20px;
      justify-content: space-between;
