    .image-frame img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    .image-badge {
      position: absolute;
      top: 16px;
      left: 16px;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(20, 32, 51, 0.74);
      color: #fff;
      font-size: 0.875rem;
      font-weight: 600;
    }

    h1,
    h2,
    p {
      margin: 0;
    }

    h1 {
      font-size: clamp(2rem, 3vw, 3rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .subcopy {
      margin-top: 12px;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.6;
