      color: var(--text);
      background: #eef4ff;
      border: 1px solid rgba(37, 99, 235, 0.12);
    }

    .trigger {
      color: #fff;
      background: linear-gradient(180deg, var(--danger) 0%, var(--danger-strong) 100%);
      box-shadow: 0 12px 24px rgba(220, 38, 38, 0.22);
    }

    .button-danger {
      color: #fff;
      background: linear-gradient(180deg, var(--danger) 0%, var(--danger-strong) 100%);
    }

    .button-secondary:hover,
    .trigger:hover,
    .button-danger:hover {
      transform: translateY(-1px);
    }

    .danger-note {
      display: flex;
      gap: 12px;
      padding: 16px;
      border-radius: 18px;
      background: var(--danger-soft);
      color: #7f1d1d;
      line-height: 1.55;
    }

    .danger-note svg {
      flex: none;
      margin-top: 2px;
    }

    dialog {
      width: min(100% - 32px, 440px);
      border: 0;
      padding: 0;
      border-radius: 24px;
      box-shadow: 0 30px 80px rgba(15, 23, 42, 0.32);
      background: transparent;
    }

    dialog::backdrop {
      background: rgba(15, 23, 42, 0.52);
      backdrop-filter: blur(6px);
    }

    .dialog-card {
      padding: 24px;
      background: #fff;
      border-radius: 24px;
      border: 1px solid rgba(20, 32, 51, 0.08);
    }

    .dialog-icon {
      width: 52px;
      height: 52px;
      display: grid;
      place-items: center;
      border-radius: 16px;
      background: var(--danger-soft);
      color: var(--danger);
      margin-bottom: 18px;
    }

    .dialog-title {
      font-size: 1.5rem;
      letter-spacing: -0.03em;
    }

    .dialog-copy {
      margin-top: 10px;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      margin-top: 24px;
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      flex-wrap: wrap;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
